import React from "react";
import { useCurrentFrame, useVideoConfig, AbsoluteFill, interpolate, Easing } from '../remotionShim';
/* Start Google Fonts Loader */
const useFontLoader = (fonts: string[]) => {
  const stableFonts = React.useMemo(() => {
    const unique = [...new Set(fonts.map(f => f.trim()))].sort();
    return unique;
  }, [fonts.join("|")]);

  React.useEffect(() => {
    const unloaded = stableFonts.filter(
      (font) =>
        !document.querySelector(
          `link[href*="${font.replace(/\s+/g, "+")}"]`
        )
    );

    if (unloaded.length === 0) return;

    const url = `https://fonts.googleapis.com/css2?${unloaded
      .map((font) => `family=${font.replace(/\s+/g, "+")}:wght@400;600;700`)
      .join("&")}&display=swap`;

    const link = document.createElement("link");
    link.rel = "stylesheet";
    link.href = url;

    document.head.appendChild(link);
  }, [stableFonts]);
};
/* End Google Fonts Loader */



export type HologramFloatingImageProps = Record<string, any>;

const HologramFloatingImage: React.FC<HologramFloatingImageProps> = ({
  backgroundColor = "#0a0a0a",
  transparentBackground = true,
  durationInSeconds = 8,
  imageUrl = "https://images.unsplash.com/photo-1579546929518-9e396f3cc809?w=800&q=80",
  imageScale = 1,
  shadowIntensity = 0.25,
  glowColor = "#00ffc8",
  enableMicroPulse = true,
}) => {
  useFontLoader(["Inter"]);

  const frame = useCurrentFrame();
  const { fps, width, height } = useVideoConfig();
  const durationInFrames = durationInSeconds * fps;

  const bgColor = transparentBackground ? `${backgroundColor}00` : backgroundColor;

  // Safe animation durations (prevents overlapping on short durations)
  const fadeInDuration = Math.min(30, durationInFrames / 2);
  const buildInDuration = Math.min(45, durationInFrames / 2);
  const fadeOutDuration = Math.min(30, durationInFrames / 2);
  const buildOutDuration = Math.min(45, durationInFrames / 2);

  // Fade in animation
  const fadeIn = interpolate(frame, [0, fadeInDuration], [0, 1], {
    extrapolateRight: "clamp",
    easing: Easing.bezier(0.33, 1, 0.68, 1),
  });

  // Fade out animation
  const fadeOut = interpolate(frame, [durationInFrames - fadeOutDuration, durationInFrames], [0, 1], {
    extrapolateLeft: "clamp",
    extrapolateRight: "clamp",
    easing: Easing.bezier(0.33, 1, 0.68, 1),
  });

  // Upward float animation
  const floatOffset = interpolate(frame, [0, durationInFrames], [height * 0.05, 0], {
    extrapolateRight: "clamp",
    easing: Easing.bezier(0.33, 1, 0.68, 1),
  });

  // Bottom-to-top scan reveal build in
  const scanReveal = interpolate(frame, [0, buildInDuration], [0, 1], {
    extrapolateRight: "clamp",
    easing: Easing.bezier(0.33, 1, 0.68, 1),
  });

  // Top-to-bottom wipe build out
  const scanOut = interpolate(frame, [durationInFrames - buildOutDuration, durationInFrames], [0, 1], {
    extrapolateLeft: "clamp",
    extrapolateRight: "clamp",
    easing: Easing.bezier(0.33, 1, 0.68, 1),
  });

  // Ambient glow pulse (slow breathing effect)
  const glowPulse = interpolate(
    Math.sin((frame / fps) * Math.PI * 0.5),
    [-1, 1],
    [0.6, 1],
  );

  // Micro pulse (very subtle)
  const microPulse = enableMicroPulse
    ? interpolate(
        Math.sin((frame / fps) * Math.PI * 2),
        [-1, 1],
        [0.98, 1.02],
      )
    : 1;

  // Scan line animation
  const scanLinePosition = interpolate(frame, [0, durationInFrames], [0, 1], {
    extrapolateRight: "wrap",
  });

  const imageSize = Math.min(width, height) * 0.6 * imageScale;
  const combinedClipPath = `inset(${Math.max((1 - scanReveal) * 100, scanOut * 100)}% 0 0 0)`;
  const containerOpacity = Math.max(0, fadeIn - fadeOut);

  return (
    <AbsoluteFill
      style={{
        backgroundColor: bgColor,
        fontFamily: "Inter",
        transition: "none",
      }}
    >
      {/* Holographic Image Container */}
      <div
        style={{
          position: "absolute",
          left: width * 0.5,
          top: height * 0.5 + floatOffset,
          transform: `translate(-50%, -50%) scale(${fadeIn * microPulse})`,
          opacity: containerOpacity,
          transition: "none",
        }}
      >
        {/* Outer Glow */}
        <div
          style={{
            position: "absolute",
            width: imageSize + 60,
            height: imageSize + 60,
            left: "50%",
            top: "50%",
            transform: "translate(-50%, -50%)",
            borderRadius: "12px",
            background: `radial-gradient(circle, ${glowColor}${Math.round(glowPulse * 30).toString(16).padStart(2, "0")} 0%, transparent 70%)`,
            filter: "blur(30px)",
            transition: "none",
          }}
        />

        {/* Drop Shadow */}
        <div
          style={{
            position: "absolute",
            width: imageSize * 0.9,
            height: imageSize * 0.15,
            left: "50%",
            top: "100%",
            transform: `translate(-50%, ${imageSize * 0.15}px)`,
            borderRadius: "50%",
            background: `radial-gradient(circle, rgba(0, 0, 0, ${shadowIntensity}) 0%, transparent 70%)`,
            filter: "blur(25px)",
            transition: "none",
          }}
        />

        {/* Main Image Container */}
        <div
          style={{
            position: "relative",
            width: imageSize,
            height: imageSize,
            transition: "none",
          }}
        >
          {/* Image with combined reveal/hide clip */}
          <div
            style={{
              position: "absolute",
              width: "100%",
              height: "100%",
              clipPath: combinedClipPath,
              transition: "none",
            }}
          >
            <img
              src={imageUrl}
              alt="Holographic Image"
              style={{
                width: "100%",
                height: "100%",
                objectFit: "cover",
                borderRadius: "12px",
                transition: "none",
              }}
            />
          </div>

          {/* Scan Lines Overlay */}
          <svg
            style={{
              position: "absolute",
              width: "100%",
              height: "100%",
              pointerEvents: "none",
              borderRadius: "12px",
              overflow: "hidden",
              clipPath: combinedClipPath,
              transition: "none",
            }}
          >
            <defs>
              <pattern
                id="scanlines"
                patternUnits="userSpaceOnUse"
                width="100%"
                height="4"
              >
                <line
                  x1="0"
                  y1="0"
                  x2="100%"
                  y2="0"
                  stroke={glowColor}
                  strokeWidth="0.5"
                  opacity="0.15"
                />
              </pattern>
            </defs>
            <rect
              width="100%"
              height="100%"
              fill="url(#scanlines)"
              style={{ transition: "none" }}
            />
          </svg>

          {/* Animated Scan Line */}
          <div
            style={{
              position: "absolute",
              width: "100%",
              height: "3px",
              top: `${scanLinePosition * 100}%`,
              background: `linear-gradient(to bottom, transparent, ${glowColor}aa, transparent)`,
              boxShadow: `0 0 15px ${glowColor}`,
              filter: "blur(2px)",
              opacity: Math.max(0, glowPulse * 0.6 * (1 - scanOut)),
              transition: "none",
            }}
          />

          {/* Corner Accents */}
          {[
            { top: -8, left: -8 },
            { top: -8, right: -8 },
            { bottom: -8, left: -8 },
            { bottom: -8, right: -8 },
          ].map((pos, idx) => (
            <div
              key={idx}
              style={{
                position: "absolute",
                ...pos,
                width: "20px",
                height: "20px",
                borderTop: pos.top !== undefined ? `2px solid ${glowColor}` : "none",
                borderBottom: pos.bottom !== undefined ? `2px solid ${glowColor}` : "none",
                borderLeft: pos.left !== undefined ? `2px solid ${glowColor}` : "none",
                borderRight: pos.right !== undefined ? `2px solid ${glowColor}` : "none",
                borderTopLeftRadius: pos.top !== undefined && pos.left !== undefined ? "4px" : "0",
                borderTopRightRadius: pos.top !== undefined && pos.right !== undefined ? "4px" : "0",
                borderBottomLeftRadius: pos.bottom !== undefined && pos.left !== undefined ? "4px" : "0",
                borderBottomRightRadius: pos.bottom !== undefined && pos.right !== undefined ? "4px" : "0",
                boxShadow: `0 0 10px ${glowColor}${Math.round(glowPulse * 60).toString(16).padStart(2, "0")}`,
                opacity: containerOpacity,
                transition: "none",
              }}
            />
          ))}
        </div>
      </div>
    </AbsoluteFill>
  );
};

export default HologramFloatingImage;